/**
 * Merge the persisted (user) skills with the default set so the defaults are pre-added
 * for every user, unless the user has their own skill with the same (case-insensitive)
 * name — which then wins and is not duplicated.
 */
export function mergeSkillsWithDefaults(userSkills: Skill[]): Skill[] {
  const seen = new Set<string>();
  const result: Skill[] = [];

  // User's own skills first so they are never shadowed by a default.
  for (const skill of userSkills) {
    const key = skill.name?.trim().toLowerCase();
    if (!key || seen.has(key)) continue;
    seen.add(key);
    result.push(skill);
  }

  // Pre-add any default not already present.
  for (const skill of DEFAULT_SKILLS) {
    const key = skill.name.trim().toLowerCase();
    if (seen.has(key)) continue;
    seen.add(key);
    result.push(skill);
  }

  return result;
}
